mapper.select:
SELECT '약제' AS part , NVL(cm.CODENAME_1, p.MEDICINE_CODE) AS itemName , CASE WHEN p.PRESCRIPTION_STATUS = 'Y' THEN '조제완료' ELSE '대기' END AS statusLabel , CASE WHEN p.PRESCRIPTION_STATUS = 'Y' THEN 'Y' ELSE 'N' END AS doneYn FROM DOCTOR_PRESCRIPTION p LEFT JOIN MEDICINE m ON m.MEDICINE_CODE = p.MEDICINE_CODE LEFT JOIN COMMONCODE cm ON cm.COMMONCODE_NUMBER = m.MEDICINE_NAME WHERE p.MEDICAL_NUMBER = #{medicalNumber}
UNION ALL
SELECT '주사' , NVL(cm.CODENAME_1, i.MEDICINE_CODE) , CASE WHEN i.INJECTED_YN = 'Y' THEN '시행완료' ELSE '미시행' END , CASE WHEN i.INJECTED_YN = 'Y' THEN 'Y' ELSE 'N' END FROM OUTPATIENTNURSE_INJECTION i LEFT JOIN MEDICINE m ON m.MEDICINE_CODE = i.MEDICINE_CODE LEFT JOIN COMMONCODE cm ON cm.COMMONCODE_NUMBER = m.MEDICINE_NAME WHERE i.MEDICAL_NUMBER = #{medicalNumber}
UNION ALL
SELECT '물리치료' , r.TREATMENT_ITEM_NAME , r.TREATMENT_STATUS , CASE WHEN r.TREATMENT_STATUS = '치료완료' THEN 'Y' ELSE 'N' END FROM PHYSICALTHERAPIST_RECORDS r WHERE r.MEDICAL_NUMBER = #{medicalNumber}
